      "Agreguj to, co pozwala Twoje środowisko, oceniaj role przy profilu i trzymaj każdą aplikację w jednej ścieżce. Gdy pojawi się automatyzacja, zostaje w granicach, które ustawiasz. Twoja kariera nie jest czarną skrzynką.",
    storyCh3Kicker: "03 · Łuk",
    storyCh3Title: "Zasłuż na przewagę, zanim poleci kolejny feature.",
    storyCh3Body:
      "Każdy rozdział musi zasłużyć na następny. Faza 1 to ścieżka aplikacji, której można zaufać. Potem autonomia, która pokazuje się w logach, eksportach i ciszy nocnej, a nie w hasełkach marketingowych.",
    timelineEyebrow: "Roadmapa",
    timelineTitle: "Oś czasu, którą czuć",
    timelineSubtitle: "Kolejność kamieni milowych usuwa tarcie, zanim dołożymy autonomię.",
    timeline1When: "Faza 1 · Teraz",
    timeline1Title: "Odkrywaj · Dopasuj · Śledź",
    timeline1Body:
      "Publiczne ogłoszenia, ranking przy profilu i status aplikacji w jednym miejscu — z myślą o przejrzystej, zaufanej powierzchni od pierwszego dnia.",
    timeline2When: "Faza 2",
    timeline2Title: "Mądrzejszy ruch",
    timeline2Body:
      "Akcje zbiorcze, bogatsze wyjaśnienia dopasowania i sygnały, które szanują geografie i godziny ciszy z konfiguracji.",
    timeline3When: "Faza 3",
    timeline3Title: "Pętle autonomiczne",
    timeline3Body:
      "Auto-aplikacja tam, gdzie portale pozwalają, okna rozmów liczące się z kalendarzem, eksporty pod compliance. Wdrażamy w miarę zaufania, nie jak kampanię „wow”.",
    faqEyebrow: "FAQ",
    faqTitle: "Pytania i odpowiedzi",
    faqPrivacyLink: "Polityka prywatności",
    audienceEyebrow: "Dla kogo",
    audienceDraftBadge: "Roboczo",
    audienceTitle: "Trzy oddzielne powierzchnie produktu",
    audienceLead:
      "Trzy produkty, trzy rozliczenia: kandydat (Stripe), rekruter (faktura), firma (rocznie). Wybierz personę i nie myl planów.",
    audienceCandidateTitle: "Kandydaci",
    audienceCandidateBody:
      "Po przerwie kalendarz powinien pokazywać krótką listę rozmów wartych czasu, a nie spam. TWIN zbiera oferty z włączonych portali, rankuje je do profilu i trzyma jedną ścieżkę aplikacji. Tam, gdzie to możliwe, dochodzi inteligencja CV i auto-aplikacja. Po starcie w roli: lekki podgląd i skrót w ciszy, żeby zostać w miesięcznym nawyku zamiast paniki w kartach.",
    audienceRecruiterTitle: "Rekruterzy i sourcerzy",
    audienceRecruiterBody:
      "Po przerwie chcesz krótką kolejkę dopasowanych profili do akceptacji lub odrzucenia, a nie zalewę CV. Listy obserwowanych, paczki dla hiring managera, presety zgodności i rozliczenie per miejsce są pod akceptację zbiorczą, nie pod surowy wolumen.",
